from html.parser import HTMLParser
from pathlib import Path
import re
class Page(HTMLParser):
 def __init__(self): super().__init__(); self.skip=False; self.parts=[]
 def handle_starttag(self,t,a):
  if t in ('style','script'): self.skip=True
  if t=='a':
   u=dict(a).get('href','')
   if u.startswith('mailto:'): self.parts.append(u)
 def handle_endtag(self,t):
  if t in ('style','script'): self.skip=False
 def handle_data(self,d):
  if not self.skip and d.strip(): self.parts.append(' '.join(d.split()))
for p in sorted(Path('products/services/sqlite-training-buyer/raw/').glob('*.html')):
 parser=Page(); parser.feed(p.read_text()); print(p.name)
 for s in dict.fromkeys(parser.parts):
  if re.search(r'\bSQL\b|partner|compound|mailto:|Toronto|corporate|hands.on',s,re.I): print(s[:480])
